package com.fasterxml.jackson.dataformat.xml.deser;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.ObjectCodec;
import com.fasterxml.jackson.dataformat.xml.PackageVersion;
import com.fasterxml.jackson.dataformat.xml.XmlMapper;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.HashSet;
import java.util.Set;
import javax.xml.stream.XMLStreamReader;
import javax.xml.stream.XMLStreamWriter;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class FromXmlParser_nextTextValue_TriageGen0Test {

    private FromXmlParser parser;

    @Mock
    private IOContext ioContext;
    @Mock
    private ObjectCodec codec;
    @Mock
    private XMLStreamReader xmlReader;
    @Mock
    private XmlXmlTokenStream xmlTokens; // Assuming XmlTokenStream is mockable or using a mock-friendly implementation

    // Since we cannot easily instantiate the internal XmlTokenStream without a real reader,
    // we use reflection to inject mocks into the parser for unit testing the logic branches.

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        parser = new FromXmlParser(ioContext, 0, 0, codec, xmlReader);

        // Injecting the mock xmlTokens via reflection because it's a private field
        setPrivateField(parser, "_xmlTokens", xmlTokens);
    }

    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testNextTextValue_AlreadyHasNextToken_String() throws Exception {
        setPrivateField(parser, "_nextToken", JsonToken.VALUE_STRING);
        setPrivateField(parser, "_currText", "hello");
        setPrivateField(parser, "_currToken", JsonToken.VALUE_STRING);

        String result = parser.nextTextValue();

        assertEquals("hello", result);
        assertNull(getPrivateField(parser, "_nextToken"));
    }

    @Test
    public void testNextTextValue_AlreadyHasNextToken_Other() throws Exception {
        setPrivateField(parser, "_nextToken", JsonToken.START_OBJECT);
        // _updateState is called, we just check it returns null
        String result = parser.nextTextValue();
        assertNull(result);
    }

    @Test
    public void testNextTextValue_XmlStartElement_MayBeLeafTrue() throws Exception {
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_START_ELEMENT);
        setPrivateField(parser, "_mayBeLeaf", true);

        // Mocking ParsingContext
        XmlReadContext mockContext = mock(XmlReadContext.class);
        XmlReadContext childContext = mock(XmlReadContext.class);
        when(mockContext.createChildObjectContext(anyInt(), anyInt())).thenReturn(childContext);
        setPrivateField(parser, "_parsingContext", mockContext);

        String result = parser.nextTextValue();

        assertNull(result);
        assertEquals(JsonToken.FIELD_NAME, getPrivateField(parser, "_nextToken"));
        assertEquals(JsonToken.START_OBJECT, getPrivateField(parser, "_currToken"));
        verify(mockContext).createChildObjectContext(-1, -1);
    }

    @Test
    public void testNextTextValue_XmlStartElement_InArray() throws Exception {
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_START_ELEMENT);
        setPrivateField(parser, "_mayBeLeaf", false);

        XmlReadContext mockContext = mock(XmlReadContext.class);
        when(mockContext.inArray()).thenReturn(true);
        setPrivateField(parser, "_parsingContext", mockContext);

        // The loop will continue
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_ATTRIBUTE_VALUE);
        when(xmlTokens.getText()).thenReturn("attrVal");

        parser.nextTextValue();

        assertTrue((Boolean) getPrivateField(parser, "_mayBeLeaf"));
    }

    @Test
    public void testNextTextValue_XmlStartElement_WithNamesToWrap() throws Exception {
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_START_ELEMENT);
        setPrivateField(parser, "_mayBeLeaf", false);
        setPrivateField(parser, "_namesToWrap", new HashSet<String>() {{ add("wrapMe"); }});

        XmlReadContext mockContext = mock(XmlReadContext.class);
        when(mockContext.createChildObjectContext(anyInt(), anyInt())).thenReturn(mock(XmlReadContext.class));
        setPrivateField(parser, "_parsingContext", mockContext);
        when(xmlTokens.getLocalName()).thenReturn("wrapMe");

        parser.nextTextValue();

        verify(xmlTokens).repeatStartElement();
        assertEquals(JsonToken.FIELD_NAME, getPrivateField(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_XmlEndElement_MayBeLeafTrue() throws Exception {
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_END_ELEMENT);
        setPrivateField(parser, "_mayBeLeaf", true);

        String result = parser.nextTextValue();

        assertEquals("", result);
        assertFalse((Boolean) getPrivateField(parser, "_mayBeLeaf"));
        assertEquals(JsonToken.VALUE_STRING, getPrivateField(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_XmlEndElement_InArray() throws Exception {
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_END_ELEMENT);
        setPrivateField(parser, "_mayBeLeaf", false);

        XmlReadContext mockContext = mock(XmlReadContext.class);
        XmlReadContext parentContext = mock(XmlReadContext.class);
        when(mockContext.inArray()).thenReturn(true);
        when(mockContext.getParent()).thenReturn(parentContext);
        when(parentContext.getNamesToWrap()).thenReturn(null);
        setPrivateField(parser, "_parsingContext", mockContext);

        parser.nextTextValue();

        assertEquals(JsonToken.END_ARRAY, getPrivateField(parser, "_currToken"));
        verify(mockContext).getParent();
    }

    @Test
    public void testNextTextValue_XmlAttributeName_MayBeLeafTrue() throws Exception {
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_ATTRIBUTE_NAME);
        setPrivateField(parser, "_mayBeLeaf", true);
        when(xmlTokens.getText()).thenReturn("attrValue");

        XmlReadContext mockContext = mock(XmlReadContext.class);
        XmlReadContext childContext = mock(XmlReadContext.class);
        when(mockContext.createChildObjectContext(anyInt(), anyInt())).thenReturn(childContext);
        setPrivateField(parser, "_parsingContext", mockContext);

        parser.nextTextValue();

        assertFalse((Boolean) getPrivateField(parser, "_mayBeLeaf"));
        assertEquals(JsonToken.FIELD_NAME, getPrivateField(parser, "_nextToken"));
        assertEquals("attrValue", getPrivateField(parser, "_currText"));
        assertEquals(JsonToken.START_OBJECT, getPrivateField(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_XmlAttributeName_NotMayBeLeaf() throws Exception {
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_ATTRIBUTE_NAME);
        setPrivateField(parser, "_mayBeLeaf", false);
        when(xmlTokens.getLocalName()).thenReturn("attrName");

        XmlReadContext mockContext = mock(XmlReadContext.class);
        setPrivateField(parser, "_parsingContext", mockContext);

        parser.nextTextValue();

        verify(mockContext).setCurrentName("attrName");
        assertEquals(JsonToken.FIELD_NAME, getPrivateField(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_XmlAttributeValue() throws Exception {
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_ATTRIBUTE_VALUE);
        when(xmlTokens.getText()).thenReturn("val");

        parser.nextTextValue();

        assertEquals("val", getPrivateField(parser, "_currText"));
        assertEquals(JsonToken.VALUE_STRING, getPrivateField(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_XmlText_MayBeLeafTrue() throws Exception {
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_TEXT);
        when(xmlTokens.getText()).thenReturn("textContent");
        setPrivateField(parser, "_mayBeLeaf", true);

        String result = parser.nextTextValue();

        assertEquals("textContent", result);
        assertFalse((Boolean) getPrivateField(parser, "_mayBeLeaf"));
        verify(xmlTokens).skipEndElement();
        assertEquals(JsonToken.VALUE_STRING, getPrivateField(parser, "_currToken"));
    }

    @Test
    public void testNextTextValue_XmlText_NotMayBeLeaf() throws Exception {
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_TEXT);
        when(xmlTokens.getText()).thenReturn("textContent");
        setPrivateField(parser, "_mayBeLeaf", false);
        setPrivateField(parser, "_cfgNameForTextElement", "textProp");

        XmlReadContext mockContext = mock(XmlReadContext.class);
        setPrivateField(parser, "_parsingContext", mockContext);

        parser.nextTextValue();

        verify(mockContext).setCurrentName("textProp");
        assertEquals(JsonToken.FIELD_NAME, getPrivateField(parser, "_currToken"));
        assertEquals(JsonToken.VALUE_STRING, getPrivateField(parser, "_nextToken"));
    }

    @Test
    public void testNextTextValue_XmlEnd() throws Exception {
        when(xmlTokens.next()).thenReturn(XmlTokenStream.XML_END);

        parser.nextTextValue();

        assertNull(getPrivateField(parser, "_currToken"));
    }

    private Object getPrivateField(Object target, String fieldName) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(target);
    }
}
